import gsap from 'gsap';import {ScrollTrigger} from 'gsap/ScrollTrigger';import {initLightningOpening} from './opening.js';
export function initEffects(reduced){
 if(document.body.dataset.page==='admin')return;
 if(!reduced){
  document.querySelectorAll('.intro-grid h2,.people-copy h2,.recruit-title h1,.page-hero h1,.contact-heading h2').forEach(el=>{const walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes){if(!node.textContent.trim())continue;const span=document.createElement('span');span.className='type-line';span.innerHTML='';const inner=document.createElement('span');inner.textContent=node.textContent;span.append(inner);node.replaceWith(span)}gsap.from(el.querySelectorAll('.type-line>span'),{yPercent:110,rotate:3,stagger:.1,duration:1.1,ease:'power3.out',scrollTrigger:{trigger:el,start:'top 90%',once:true}})});
  document.querySelectorAll('.fleet-row-photo img,.recruit-team img,.company-hero-photo img').forEach(el=>gsap.fromTo(el,{yPercent:-8,scale:1.12},{yPercent:8,ease:'none',scrollTrigger:{trigger:el.parentElement,start:'top bottom',end:'bottom top',scrub:1}}));
 }
 const hero=document.querySelector('.hero-fullscreen');if(hero&&!reduced){const routes=[...hero.querySelectorAll('.hero-route path')];routes.forEach(p=>{const length=p.getTotalLength();gsap.set(p,{strokeDasharray:length,strokeDashoffset:0})});gsap.to(hero.querySelector('.hero-photo'),{yPercent:8,scale:1.07,ease:'none',scrollTrigger:{trigger:hero,start:'top top',end:'bottom top',scrub:true}});gsap.to(hero.querySelector('.hero-copy'),{y:-45,opacity:.25,ease:'none',scrollTrigger:{trigger:hero,start:'30% top',end:'bottom top',scrub:true}});gsap.fromTo(routes,{strokeDashoffset:180},{strokeDashoffset:0,ease:'none',scrollTrigger:{trigger:hero,start:'top top',end:'bottom top',scrub:true}})}
 const purpose=document.querySelector('.intro');if(purpose&&!reduced){gsap.fromTo('.word-one',{xPercent:-12},{xPercent:-35,ease:'none',scrollTrigger:{trigger:purpose,start:'top bottom',end:'bottom top',scrub:1}});gsap.fromTo('.word-two',{xPercent:-38},{xPercent:-8,ease:'none',scrollTrigger:{trigger:purpose,start:'top bottom',end:'bottom top',scrub:1}});gsap.fromTo('.purpose-portal',{clipPath:'inset(12% 27% 12% 27%)',rotate:-4},{clipPath:'inset(0% 0% 0% 0%)',rotate:0,ease:'none',scrollTrigger:{trigger:'.purpose-portal',start:'top 95%',end:'center 45%',scrub:1}});gsap.to('.purpose-portal img',{yPercent:12,scale:1.15,ease:'none',scrollTrigger:{trigger:purpose,start:'top bottom',end:'bottom top',scrub:1}})}
 if(!reduced){const crew=document.querySelector('.home-recruit');if(crew){gsap.fromTo('.people-teaser img',{scale:1.25,yPercent:-8},{scale:1,yPercent:8,ease:'none',scrollTrigger:{trigger:crew,start:'top bottom',end:'bottom top',scrub:1}});gsap.to('.recruit-kinetic',{xPercent:-25,ease:'none',scrollTrigger:{trigger:crew,start:'top bottom',end:'bottom top',scrub:1}})}}
 initLightningOpening(reduced);
}
